"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";
import { ConfettiBurst } from "./confetti";

export type TaskPriority = "none" | "low" | "normal" | "high";

export interface TaskMetaTag {
  icon?: React.ReactNode;
  label: React.ReactNode;
  /** Kleur van het label, bv. rood voor een verlopen deadline. */
  tone?: "neutral" | "accent" | "green" | "amber" | "red" | "blue" | "violet";
  /** Gekleurd bolletje vóór het label, bv. de kleur van een lijst. */
  dot?: string;
}

export interface TaskItemProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title" | "onToggle"> {
  title: React.ReactNode;
  done?: boolean;
  priority?: TaskPriority;
  /** Labels onder de titel: lijst, deadline, herhaling … */
  tags?: TaskMetaTag[];
  /** Voortgang van deeltaken, bv. { done: 2, total: 5 }. */
  progress?: { done: number; total: number };
  /** Wordt aangeroepen bij het aan- of afvinken. */
  onToggle?: (done: boolean) => void;
  /** Klik op de rij zelf. */
  onOpen?: () => void;
  /** Toont een verwijderknop; de rij schuift weg vóór de aanroep. */
  onDelete?: () => void;
  /** Confetti bij het afvinken. */
  celebrate?: boolean;
  /** Extra knoppen rechts. */
  actions?: React.ReactNode;
}

/**
 * TaskItem — één taak in een lijst: afvinken, prioriteit, labels en voortgang
 * van deeltaken. Bij het afvinken springt er confetti uit de knop.
 */
export const TaskItem = React.forwardRef<HTMLDivElement, TaskItemProps>(function TaskItem(
  {
    title,
    done = false,
    priority = "none",
    tags,
    progress,
    onToggle,
    onOpen,
    onDelete,
    celebrate = true,
    actions,
    className,
    children,
    ...rest
  },
  ref
) {
  const [burst, setBurst] = React.useState(false);
  const [removing, setRemoving] = React.useState(false);
  const wasDone = React.useRef(done);

  React.useEffect(() => {
    if (!wasDone.current && done && celebrate) setBurst(true);
    wasDone.current = done;
  }, [done, celebrate]);

  const remove = () => {
    setRemoving(true);
    window.setTimeout(() => onDelete?.(), 260);
  };

  return (
    <div
      ref={ref}
      data-done={done ? "" : undefined}
      data-removing={removing ? "" : undefined}
      className={cn("pxui-task", `pxui-task-prio-${priority}`, onOpen && "pxui-task-clickable", className)}
      onClick={onOpen}
      {...rest}
    >
      <span className="pxui-task-prio" aria-hidden="true" />

      <button
        type="button"
        role="checkbox"
        aria-checked={done}
        aria-label={done ? "Vinkje weghalen" : "Afvinken"}
        className="pxui-task-check"
        onClick={(event) => {
          event.stopPropagation();
          onToggle?.(!done);
        }}
      >
        <Icon name="check" size={14} strokeWidth={3} />
        {burst && <ConfettiBurst onDone={() => setBurst(false)} />}
      </button>

      <div className="pxui-task-body">
        <div className="pxui-task-title">{title}</div>

        {(tags?.length || progress) && (
          <div className="pxui-task-meta">
            {tags?.map((tag, index) => (
              <span key={index} className={cn("pxui-task-tag", tag.tone && `pxui-task-tag-${tag.tone}`)}>
                {tag.dot && <span className="pxui-task-tag-dot" style={{ background: tag.dot }} />}
                {tag.icon}
                {tag.label}
              </span>
            ))}

            {progress && progress.total > 0 && (
              <span className="pxui-task-progress">
                <span className="pxui-task-progress-bar">
                  <i style={{ width: `${(progress.done / progress.total) * 100}%` }} />
                </span>
                {progress.done}/{progress.total}
              </span>
            )}
          </div>
        )}

        {children}
      </div>

      <div className="pxui-task-actions" onClick={(event) => event.stopPropagation()}>
        {actions}
        {onOpen && (
          <button type="button" className="pxui-task-action" aria-label="Openen" onClick={onOpen}>
            <Icon name="chevronRight" size={16} />
          </button>
        )}
        {onDelete && (
          <button
            type="button"
            className="pxui-task-action pxui-task-action-danger"
            aria-label="Verwijderen"
            onClick={remove}
          >
            <Icon name="trash" size={15} />
          </button>
        )}
      </div>
    </div>
  );
});

export interface TaskListProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Rand en schaduw rond de lijst. */
  bordered?: boolean;
}

/** TaskList — container voor TaskItems. */
export const TaskList = React.forwardRef<HTMLDivElement, TaskListProps>(function TaskList(
  { bordered, className, ...rest },
  ref
) {
  return (
    <div ref={ref} className={cn("pxui-tasklist", bordered && "pxui-tasklist-bordered", className)} {...rest} />
  );
});

/* ============================ TaskItem ============================ */
.pxui-tasklist { display: flex; flex-direction: column; min-width: 0; }
.pxui-tasklist-bordered {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-lg); box-shadow: var(--sh-sm); overflow: hidden;
}
.pxui-tasklist > .pxui-task + .pxui-task { border-top: 1px solid var(--border); }

.pxui-task {
  --pxui-task-color: var(--text-3);
  position: relative;
  display: flex; align-items: flex-start; gap: 12px;
  padding: calc(13px * var(--density)) 16px calc(13px * var(--density)) 18px;
  background: var(--surface); min-width: 0;
  transition: background var(--dur-fast), opacity var(--dur), transform var(--dur);
}
.pxui-task-clickable { cursor: pointer; }
.pxui-task-clickable:hover { background: var(--surface-hover); }

.pxui-task[data-removing] {
  opacity: 0; transform: translateX(24px);
  pointer-events: none;
}

/* ---------- Prioriteitsstreepje ---------- */
.pxui-task-prio {
  position: absolute; left: 0; top: 8px; bottom: 8px; width: 3px;
  border-radius: 0 3px 3px 0; background: var(--pxui-task-color);
}
.pxui-task-prio-none { --pxui-task-color: transparent; }
.pxui-task-prio-low { --pxui-task-color: var(--blue); }
.pxui-task-prio-normal { --pxui-task-color: var(--amber); }
.pxui-task-prio-high { --pxui-task-color: var(--red); }

/* ---------- Afvinken ---------- */
.pxui-task-check {
  position: relative; flex: none; display: grid; place-items: center;
  width: 22px; height: 22px; margin-top: 1px;
  border: 1.5px solid var(--border-strong); border-radius: var(--r-full);
  background: var(--surface); color: var(--accent-fg); cursor: pointer;
  transition: background var(--dur-fast), border-color var(--dur-fast);
}
.pxui-task-check svg { opacity: 0; transform: scale(.5); transition: opacity var(--dur-fast), transform var(--dur-fast); }
.pxui-task-check:hover { border-color: var(--accent); }
.pxui-task-check:focus-visible { outline: none; box-shadow: var(--ring); }
.pxui-task[data-done] .pxui-task-check { background: var(--accent); border-color: var(--accent); }
.pxui-task[data-done] .pxui-task-check svg { opacity: 1; transform: none; }

/* ---------- Tekst ---------- */
.pxui-task-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 5px; }
.pxui-task-title {
  font-size: 14px; font-weight: 550; color: var(--text); line-height: 1.4;
  word-break: break-word;
}
.pxui-task[data-done] .pxui-task-title { color: var(--text-3); text-decoration: line-through; }

.pxui-task-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; }
.pxui-task-tag {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 2px 8px; border-radius: var(--r-full);
  background: var(--surface-3); border: 1px solid var(--border);
  font-size: 11.5px; font-weight: 600; color: var(--text-3); white-space: nowrap;
}
.pxui-task-tag svg { width: 13px; height: 13px; }
.pxui-task-tag-dot { width: 7px; height: 7px; border-radius: var(--r-full); flex: none; }
.pxui-task-tag-accent { background: var(--accent-tint); border-color: var(--accent-border); color: var(--accent-active); }
.pxui-task-tag-green { background: var(--green-tint); border-color: var(--green-border); color: var(--green); }
.pxui-task-tag-amber { background: var(--amber-tint); border-color: var(--amber-border); color: var(--amber); }
.pxui-task-tag-red { background: var(--red-tint); border-color: var(--red-border); color: var(--red); }
.pxui-task-tag-blue { background: var(--blue-tint); border-color: var(--blue-border); color: var(--blue); }
.pxui-task-tag-violet { background: var(--violet-tint); border-color: var(--violet-border); color: var(--violet); }

.pxui-task-progress {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 11.5px; font-weight: 600; color: var(--text-3);
  font-variant-numeric: tabular-nums;
}
.pxui-task-progress-bar {
  display: block; width: 46px; height: 4px;
  background: var(--surface-3); border-radius: var(--r-full); overflow: hidden;
}
.pxui-task-progress-bar i {
  display: block; height: 100%; background: var(--accent);
  border-radius: inherit; transition: width var(--dur) var(--ease-out);
}

/* ---------- Acties ---------- */
.pxui-task-actions {
  flex: none; display: flex; align-items: center; gap: 2px;
  opacity: 0; transition: opacity var(--dur-fast);
}
.pxui-task:hover .pxui-task-actions,
.pxui-task:focus-within .pxui-task-actions { opacity: 1; }

.pxui-task-action {
  display: grid; place-items: center; width: 30px; height: 30px;
  border: none; background: transparent; border-radius: var(--r-xs);
  color: var(--text-3); cursor: pointer;
  transition: background var(--dur-fast), color var(--dur-fast);
}
.pxui-task-action:hover { background: var(--surface-3); color: var(--text); }
.pxui-task-action:focus-visible { outline: none; box-shadow: var(--ring); }
.pxui-task-action-danger:hover { background: var(--red-tint); color: var(--red); }

@media (max-width: 560px) {
  .pxui-task-actions { opacity: 1; }
}
